<div class="form-group"><label for="tt-name">Timetable name</label><input id="tt-name" name="name" class="form-control" required maxlength="100" value="{{ old('name', optional($record)->name) }}" placeholder="CS Semester 6 — Section A"></div>
<div class="form-group"><label for="tt-class">Semester</label><select id="tt-class" name="my_class_id" required class="form-control"><option value="">Select semester</option>@foreach($classes as $class)<option value="{{ $class->id }}" {{ old('my_class_id', optional($record)->my_class_id) == $class->id ? 'selected' : '' }}>{{ $class->name }}</option>@endforeach</select></div>
<div class="form-group"><label for="tt-section">Section</label><select id="tt-section" name="section_id" required class="form-control"><option value="">Select section</option>@foreach($classes as $class) @foreach($class->section as $section)<option data-class="{{ $class->id }}" value="{{ $section->id }}" {{ old('section_id', optional($record)->section_id) == $section->id ? 'selected' : '' }}>{{ $section->name }}</option>@endforeach @endforeach</select></div>
<script>document.addEventListener('DOMContentLoaded',function(){const c=document.getElementById('tt-class'),s=document.getElementById('tt-section');function filter(){Array.from(s.options).forEach(o=>{o.disabled=!!o.value&&o.dataset.class!==c.value;o.hidden=o.disabled;});if(s.selectedOptions[0]?.disabled)s.value='';}c.addEventListener('change',filter);filter();});</script>
